#include <linux/cgroup.h>
#include <linux/eventfd.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <linux/vmalloc.h>

void unregister_memcg_oom_event_threshold(struct cgroup *cgrp, struct cftype *cft, struct eventfd_ctx *eventfd) {
    struct mem_cgroup *memcg = cgroup_to_mem_cgroup(cgrp);
    struct memcg_eventfd_list *list = &memcg->oom_eventfds;
    int i, j, new_size;
    struct eventfd_ctx *tmp_eventfd;
    struct memcg_eventfd_list *new_list = NULL;

    mutex_lock(&list->threshold_mutex);

    for (i = 0; i < list->count; ++i) {
        if (list->eventfds[i] == eventfd) {
            new_size = list->count - 1;

            if (new_size == 0) {
                kfree(list->eventfds);
                list->eventfds = NULL;
                list->count = 0;
                mutex_unlock(&list->threshold_mutex);
                return;
            }

            new_list = kmalloc(sizeof(struct memcg_eventfd_list), GFP_KERNEL);
            if (!new_list) {
                mutex_unlock(&list->threshold_mutex);
                return;
            }

            new_list->eventfds = kmalloc(new_size * sizeof(struct eventfd_ctx *), GFP_KERNEL);
            if (!new_list->eventfds) {
                kfree(new_list);
                mutex_unlock(&list->threshold_mutex);
                return;
            }

            new_list->count = new_size;
            new_list->threshold_mutex = list->threshold_mutex;

            for (j = 0; j < new_size; ++j) {
                if (j < i) {
                    new_list->eventfds[j] = list->eventfds[j];
                } else {
                    new_list->eventfds[j] = list->eventfds[j + 1];
                }
            }

            kfree(list->eventfds);
            *list = *new_list;
            kfree(new_list);
            mutex_unlock(&list->threshold_mutex);
            return;
        }
    }

    mutex_unlock(&list->threshold_mutex);
}
